import os, sys, re, shutil, tempfile, json, tomllib, hashlib

def sha256_file(path):
    h = hashlib.sha256()
    with open(path, \"rb\") as f:
        for chunk in iter(lambda: f.read(65536), b\"\"):
            h.update(chunk)
    return h.hexdigest()

pkg_root = sys.argv[1]

tmp_home = tempfile.mkdtemp(prefix=\"audit_reinst_home_\")
agents_dst = os.path.join(tmp_home, \"agents\")
os.makedirs(agents_dst, exist_ok=True)
agents_src = os.path.join(pkg_root, \"agents\")

for fname in os.listdir(agents_src):
    if not fname.endswith(\".toml\"): continue
    shutil.copy2(os.path.join(agents_src, fname), os.path.join(agents_dst, fname))

cfg_path = os.path.join(tmp_home, \"config.toml\")
shutil.copy2(os.path.join(pkg_root, \"config\", \"config.toml.example\"), cfg_path)

# Add a user-specific key
with open(cfg_path, \"a\", encoding=\"utf-8\") as f:
    f.write('\\n[user]\\nmy_custom_key = \"must-survive-reinstall\"\\n')

hashes_after_first = {
    fname: sha256_file(os.path.join(agents_dst, fname))
    for fname in os.listdir(agents_dst) if fname.endswith(\".toml\")
}

# Second install (idempotency): skip identical
skipped, replaced = [], []
for fname in os.listdir(agents_src):
    if not fname.endswith(\".toml\"): continue
    src = os.path.join(agents_src, fname)
    dst = os.path.join(agents_dst, fname)
    if sha256_file(src) == sha256_file(dst):
        skipped.append(fname)
    else:
        shutil.copy2(src, dst)
        replaced.append(fname)

print(f\"PASS  reinstall: {len(skipped)} TOMLs skipped (identical, no change)\")
if replaced:
    print(f\"INFO  reinstall: {len(replaced)} TOMLs replaced\")

# Verify user key persists
cfg_content = open(cfg_path, encoding=\"utf-8\").read()
if \"my_custom_key\" in cfg_content:
    print(f\"PASS  reinstall: user custom config key preserved\")
else:
    print(f\"FAIL  reinstall: user custom config key was overwritten"'!")

hashes_after_second = {
    fname: sha256_file(os.path.join(agents_dst, fname))
    for fname in os.listdir(agents_dst) if fname.endswith(".toml")
}

if hashes_after_first == hashes_after_second:
    print(f"PASS  reinstall idempotency: hashes unchanged after second install")
else:
    print(f"FAIL  reinstall: agent TOML hashes changed unexpectedly!")

shutil.rmtree(tmp_home, ignore_errors=True)
